package cn.cloudcurtain.tv;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import java.util.*;
final class FileBrowserInteractionsLiveCheck {
 static java.lang.reflect.Field field(String name)throws Exception{return FileBrowserLiveCheck.field(name);}
 static void invoke(Instrumentation t,CloudFilesActivity a,String method)throws Exception{Method m=CloudFilesActivity.class.getDeclaredMethod(method);m.setAccessible(true);t.runOnMainSync(()->{try{m.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();}
 static void click(Instrumentation t,String label)throws Exception{
  long end=SystemClock.elapsedRealtime()+4000;while(SystemClock.elapsedRealtime()<end){AccessibilityNodeInfo root=t.getUiAutomation().getRootInActiveWindow();if(root!=null){for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(label))if(label.contentEquals(n.getText()==null?"":n.getText())&&n.isEnabled()){boolean clicked=false;if(n.isVisibleToUser()){android.graphics.Rect bounds=new android.graphics.Rect();n.getBoundsInScreen(bounds);if(bounds.width()>0&&bounds.height()>0){long now=SystemClock.uptimeMillis();android.view.MotionEvent down=android.view.MotionEvent.obtain(now,now,android.view.MotionEvent.ACTION_DOWN,bounds.centerX(),bounds.centerY(),0),up=android.view.MotionEvent.obtain(now,now+50,android.view.MotionEvent.ACTION_UP,bounds.centerX(),bounds.centerY(),0);down.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);up.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{clicked=t.getUiAutomation().injectInputEvent(down,true)&&t.getUiAutomation().injectInputEvent(up,true);}finally{down.recycle();up.recycle();}}}if(clicked){Thread.sleep(500);t.waitForIdleSync();return;}}}Thread.sleep(100);}throw new IOException("Dialog choice unavailable: "+label);
 }
 static void await(Instrumentation t,CloudFilesActivity a)throws Exception{long end=SystemClock.elapsedRealtime()+30000;final boolean[] done={false};while(SystemClock.elapsedRealtime()<end){t.runOnMainSync(()->{try{done[0]=!field("loading").getBoolean(a);}catch(Exception e){throw new RuntimeException(e);}});if(done[0]){t.waitForIdleSync();return;}Thread.sleep(150);}throw new IOException("Directory timed out");}
 static void render(Instrumentation t,CloudFilesActivity a,List<CloudApi.Entry> entries)throws Exception{Method m=CloudFilesActivity.class.getDeclaredMethod("render");m.setAccessible(true);t.runOnMainSync(()->{try{field("current").set(a,entries);field("more").setBoolean(a,false);m.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});t.waitForIdleSync();}
 static void run(Instrumentation t,Bundle r)throws Exception{
  Context c=t.getTargetContext();SharedPreferences prefs=c.getSharedPreferences("file_browser",0);Map<String,?> backup=prefs.getAll();CloudFilesActivity a=null,b=null;
  try{
   prefs.edit().clear().commit();a=(CloudFilesActivity)t.startActivitySync(new Intent(c,CloudFilesActivity.class).putExtra("provider","QUARK").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(t,a);
   final CloudFilesActivity first=a;List<CloudApi.Entry> root=new ArrayList<>((List<CloudApi.Entry>)field("current").get(a));List<CloudApi.Entry> folders=new ArrayList<>();for(CloudApi.Entry e:root)if(e.directory)folders.add(e);if(folders.size()<2)throw new IOException("Two root folders needed for column branch test");
   invoke(t,a,"chooseView");click(t,"分栏");r.putInt("view_selected",((FilePresentation.Options)field("options").get(a)).view);final CloudApi.Entry one=folders.stream().filter(e->e.name.equals("电影")).findFirst().orElse(folders.get(0));Method navigate=CloudFilesActivity.class.getDeclaredMethod("navigate",int.class,CloudApi.Entry.class);navigate.setAccessible(true);t.runOnMainSync(()->{try{navigate.invoke(first,0,one);}catch(Exception e){throw new RuntimeException(e);}});await(t,a);
   final boolean[] switched={false};final CloudApi.Entry other=folders.stream().filter(e->e!=one&&!e.name.contains("隐私")).findFirst().orElse(folders.get(1));t.runOnMainSync(()->{try{ViewGroup area=(ViewGroup)field("area").get(first);switched[0]=clickRow(area,other.name);}catch(Exception e){throw new RuntimeException(e);}});await(t,a);List<String> ids=(List<String>)field("ids").get(a);r.putBoolean("parent_row_clicked",switched[0]);r.putInt("column_depth",ids.size());if(!switched[0]||ids.size()!=2||!other.id.equals(ids.get(1)))throw new IOException("Column branch kept stale levels");r.putBoolean("columns_parent_branch",true);
   List<CloudApi.Entry> fixture=new ArrayList<>();fixture.add(new CloudApi.Entry("folder","测试文件夹",true,0));CloudApi.Entry shared=new CloudApi.Entry("shared","共享视频.mp4",false,200);shared.source="shared";fixture.add(shared);fixture.add(new CloudApi.Entry("own","个人视频.mkv",false,300));fixture.add(new CloudApi.Entry("sub","字幕.srt",false,10));
   FilePresentation.Options clean=new FilePresentation.Options();field("options").set(a,clean);render(t,a,fixture);invoke(t,a,"chooseFilters");click(t,"视频");click(t,"取消");if(!((FilePresentation.Options)field("options").get(a)).types.isEmpty())throw new IOException("Cancel applied filters");r.putBoolean("filter_cancel",true);
   invoke(t,a,"chooseFilters");click(t,"视频");click(t,"来自分享");click(t,"确定");FilePresentation.Options options=(FilePresentation.Options)field("options").get(a);if(!options.types.contains("video")||!options.sources.contains("shared")||FilePresentation.select(fixture,options).size()!=2)throw new IOException("Filter apply failed");r.putBoolean("filter_apply",true);
   invoke(t,a,"chooseSort");click(t,"按文件大小");click(t,"倒序");click(t,"确定");invoke(t,a,"chooseView");click(t,"图标");options=(FilePresentation.Options)field("options").get(a);if(options.sort!=5||!options.descending||options.view!=2)throw new IOException("Sort or view did not apply");r.putBoolean("sort_view_apply",true);
   t.runOnMainSync(a::finish);b=(CloudFilesActivity)t.startActivitySync(new Intent(c,CloudFilesActivity.class).putExtra("provider","QUARK").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(t,b);options=(FilePresentation.Options)field("options").get(b);if(options.sort!=5||!options.descending||options.view!=2||!options.types.contains("video")||!options.sources.contains("shared"))throw new IOException("Browser preferences lost on reopen");r.putBoolean("reopen_preferences",true);
   invoke(t,b,"chooseFilters");click(t,"重置");click(t,"确定");options=(FilePresentation.Options)field("options").get(b);if(!options.types.isEmpty()||!options.sources.isEmpty())throw new IOException("Filter reset failed");r.putBoolean("filter_reset",true);r.putFloat("font_scale",c.getResources().getConfiguration().fontScale);
  }finally{if(a!=null){CloudFilesActivity close=a;t.runOnMainSync(close::finish);}if(b!=null){CloudFilesActivity close=b;t.runOnMainSync(close::finish);}SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> row:backup.entrySet()){Object v=row.getValue();if(v instanceof String)edit.putString(row.getKey(),(String)v);else if(v instanceof Integer)edit.putInt(row.getKey(),(Integer)v);else if(v instanceof Boolean)edit.putBoolean(row.getKey(),(Boolean)v);else if(v instanceof Set)edit.putStringSet(row.getKey(),(Set<String>)v);}edit.commit();}
 }
 static boolean clickRow(View v,String name){if(v instanceof FileRow&&v.getContentDescription()!=null&&v.getContentDescription().toString().startsWith(name+"，")){v.performClick();return true;}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(clickRow(g.getChildAt(i),name))return true;}return false;}
}
